from lib import *
S = SS('u161')
R = J('u161'); Lv = R['levels']; d, p, a = Lv['默认'], Lv['-W clippy::pedantic'], Lv['-A clippy::all(全部允许)']
steps = [
    step(f"cargo clippy 是 rustc 的 lint 扩展。对一个故意写了不地道代码的小库,默认输出 {R['diag_n']} 条诊断,涉及 {len(R['names'])} 个 clippy lint:{'、'.join(R['names'])}。每条诊断都有 lint 名与文档链接、一个 help 给出修改建议并展示改前改后的代码:needless_return 建议把 `return s;` 改成 `s`;ptr_arg 指出 &Vec<i32> 参数应该写 &[i32](「involves a new object where a slice will do」);needless_range_loop 建议用迭代器代替 for i in 0..v.len()。", t=tl(S(1)), done=lidx(S(1), '触发的 lint', 'unneeded `return`', 'writing `&Vec`', 'loop variable `i`'), kv=KV([['needless_return', '`return s;` → `s`'], ['ptr_arg', '&Vec<i32> → &[i32]'], ['needless_range_loop', '改用迭代器']], ['ptr_arg'])),
    step(f"有些 lint 默认是 deny:`x == x`(eq_op)与对 u32 做 `x < 0`(absurd_extreme_comparisons)是 error 级别 —— 其余 {R['warn_n']} 条是 warning。所以 cargo clippy 退出码是 {R['rc']},即使大多数诊断只是风格问题。deny 的 lint 属于 correctness 组:几乎一定是 bug。", t=tl(S(2)), mark=lidx(S(2), 'error 2 条', 'deny 级别'), kv=KV([['deny(error)', '、'.join(R['deny'])], ['其余', f"{R['warn_n']} 条 warning"], ['退出码', str(R['rc'])]], ['deny(error)'])),
    step(f"lint 的等级可以调:默认配置 {d[0]} 条诊断、{d[1]} 个 lint;加 -W clippy::pedantic(更挑剔的一组)变成 {p[0]} 条、{p[1]} 个 lint,多出 {'、'.join(R['pedantic_extra'])};-A clippy::all 把 clippy 的 lint 全部允许后,clippy 的诊断没有了(只剩 rustc 自己的 {a[0]} 条),退出码 {a[2]}。", t=tl(S(3)), done=lidx(S(3), '默认', '-W clippy::pedantic', '-A clippy::all', 'pedantic 额外'), b=bars([['默认', d[0], str(d[0])], ['pedantic', p[0], str(p[0])], ['-A clippy::all', a[0], str(a[0])]], p[0], done=[0, 1, 2]), kv=KV([['默认', f'{d[0]} 条 / {d[1]} 个 lint'], ['pedantic', f'{p[0]} 条 / {p[1]} 个 lint'], ['-A clippy::all', f'{a[0]} 条']], ['pedantic'])),
    step(f"代码里用 #[allow(clippy::eq_op)] 等属性局部关闭:给 same、absurd、is_empty_len 加上 allow 后,cargo clippy 退出码 {R['after_allow'][0]},剩下的 lint 是 {'、'.join(R['after_allow'][1])}。CI 里常用 -D warnings 把所有警告当错误:这时退出码是 {R['dw']}(失败),逼着修复或显式 allow。", t=tl(S(4)), done=lidx(S(4), '加了 #[allow]', '-D warnings'), kv=KV([['#[allow(clippy::x)]', '局部关闭某条 lint'], ['-D warnings', f"警告变错误,退出码 {R['dw']}"]], ['-D warnings'])),
    step(f"cargo clippy --fix 自动应用「可机械修改」的建议:把 v.len() == 0 改成 v.is_empty()、`if b == true` 改成 `if b`、手写的 match Some/None 改成 o.map(|x| x * 2)、x.clone() 改成 x、`return s;` 改成 `s`,共改了 {len([l for l in R['fix'] if l.startswith('+')])} 行。修复后再跑,只剩 {'、'.join(R['after_fix'])} 两个 —— 它们需要改函数签名/循环结构,clippy 不会自动应用。", t=tl(S(5)), done=lidx(S(5), '--fix 退出码', '修复后再跑'), mark=lidx(S(5), '+', '-'), kv=KV([['自动修复', 'len_zero / bool_comparison / manual_map / clone_on_copy / needless_return'], ['留给你', '、'.join(R['after_fix'])]], ['留给你'])),
]
A = mkart('u161', 161, 'Rust,Clippy,lint,静态检查,真实验证,动画演示',
    f'用一个故意写得不地道的小库验证 clippy:默认 {d[0]} 条诊断、{d[1]} 个 lint(含 eq_op 与 absurd_extreme_comparisons 两个 deny 级别,cargo clippy 退出码 101);-W clippy::pedantic {p[0]} 条;#[allow] 与 -D warnings;cargo clippy --fix 改了 {len([l for l in R["fix"] if l.startswith("+")])} 行并留下 needless_range_loop 与 ptr_arg。',
    'Clippy 能抓住什么、有多挑剔、哪些问题会直接让构建失败、能自动修复多少?这篇不转述文档,直接对一份故意写坏的代码跑 cargo clippy,把诊断、等级、开关与自动修复全部亲眼看一遍。',
    [(f'{d[0]} 条', '默认配置下 clippy 对示例库的诊断数'), ('2 个', '默认就是 deny(error)的 lint:eq_op、absurd_extreme_comparisons'), (f'{len([l for l in R["fix"] if l.startswith("+")])} 行', 'cargo clippy --fix 自动修改的行数')],
    [('诊断长什么样', '<p>代码格式化见<a href="rust-rustfmt.html">rustfmt 格式化</a>;持续集成里怎么用见<a href="rust-ci.html">Rust 项目持续集成</a>。clippy 0.1.98。</p>'), ('deny 级别的 lint', None), ('lint 的等级', None), ('局部关闭与 -D warnings', None), ('自动修复', None)],
    steps, [ENV_U + '。clippy 0.1.98(随 rustc 1.98.1)', '没有验证:clippy.toml 的配置(msrv、阈值)、[lints.clippy] 在 Cargo.toml 里的写法、nursery 与 restriction 组、clippy 与 rust-analyzer 的集成、--fix 在有未提交改动时的保护、其它版本的 lint 差别'], 'Clippy')
